{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "title": "Spec",
  "description": "An unambiguous, testable specification. Every claim is verifiable or explicitly marked as a judgment call.",
  "type": "object",
  "required": ["id", "purpose", "scope", "non_goals", "acceptance_criteria"],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "description": "Unique identifier (e.g. SPEC-001)"
    },
    "purpose": {
      "type": "string",
      "description": "One paragraph: what this spec defines and why it exists"
    },
    "scope": {
      "type": "string",
      "description": "What is covered by this spec"
    },
    "non_goals": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" },
      "description": "Explicitly excluded from this spec"
    },
    "api_surface": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "signature", "description"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "signature": { "type": "string" },
          "description": { "type": "string" },
          "error_conditions": { "type": "array", "items": { "type": "string" } }
        }
      }
    },
    "acceptance_criteria": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "criterion"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "criterion": {
            "type": "string",
            "description": "A testable proposition — something that can be confirmed true or false"
          },
          "is_error_case": {
            "type": "boolean",
            "default": false,
            "description": "True if this criterion describes behavior under an error condition"
          },
          "judgment_call": {
            "type": "boolean",
            "default": false,
            "description": "True if this criterion requires human judgment to evaluate. Must include rationale."
          },
          "rationale": {
            "type": "string",
            "description": "Required when judgment_call is true"
          }
        }
      }
    },
    "linked_requirement": {
      "type": "string",
      "description": "ID of the requirement@1 this spec implements"
    },
    "linked_research": {
      "type": "string",
      "description": "ID of the research-report@1 that informed this spec"
    },
    "spec_file_path": {
      "type": "string",
      "description": "Workspace-relative path where this spec is written on disk (e.g. docs/specs/SPEC-001.json). Set by the scribe skill orchestrator after gate passes. Agents resolve it against workspace_root from the recon manifest."
    },
    "revision_note": {
      "type": "string",
      "description": "Set when this spec is a correction of a previously gated spec, typically sourced from a implementer spec_contradiction report. Describes what changed and why, citing the affected criterion_id. Absent on first drafts."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "plan@1",
  "title": "Plan",
  "description": "A sequenced implementation plan. Every task is bite-sized, with an implementation approach, exact code, the tests proving each criterion, and a commit message.",
  "type": "object",
  "required": ["goal", "architecture", "tech_stack", "tasks"],
  "additionalProperties": false,
  "properties": {
    "goal": {
      "type": "string",
      "description": "One sentence: what this plan produces"
    },
    "architecture": {
      "type": "string",
      "description": "2-3 sentences on the implementation approach"
    },
    "tech_stack": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Key libraries, frameworks, or runtimes involved"
    },
    "tasks": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "title", "files", "steps", "commit_message"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "files": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "create": { "type": "array", "items": { "type": "string" } },
              "modify": { "type": "array", "items": { "type": "string" } },
              "test": { "type": "array", "items": { "type": "string" } }
            }
          },
          "steps": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" },
            "description": "Ordered steps. Each step is one action. Code steps include exact code. Test steps include exact command and expected output."
          },
          "commit_message": {
            "type": "string",
            "description": "Conventional commit message for this task"
          },
          "depends_on": {
            "type": "array",
            "items": { "type": "string" },
            "description": "IDs of tasks that must complete before this one"
          },
          "covers_criteria": {
            "type": "array",
            "items": { "type": "string" },
            "description": "IDs of acceptance criteria from spec@1 that this task covers. challenger checks that every criterion ID appears in at least one task."
          }
        }
      }
    },
    "batches": {
      "type": "array",
      "description": "Optional grouping of tasks into cohesive subsystem/crate compilation units to allow batch execution and minimize subagent spawns.",
      "items": {
        "type": "object",
        "required": ["batch_id", "title", "target_crate", "task_ids"],
        "additionalProperties": false,
        "properties": {
          "batch_id": { "type": "string" },
          "title": { "type": "string" },
          "target_crate": { "type": "string" },
          "task_ids": { "type": "array", "items": { "type": "string" } }
        }
      }
    },
    "linked_spec": {
      "type": "string",
      "description": "ID of the spec@1 this plan implements"
    },
    "spec_file_path": {
      "type": "string",
      "description": "Workspace-relative path to the spec@1 file this plan implements (e.g. docs/specs/SPEC-001.json). Propagated from spec@1.spec_file_path. Agents resolve it against workspace_root from the recon manifest."
    },
    "plan_file_path": {
      "type": "string",
      "description": "Workspace-relative path where this plan is written on disk (e.g. docs/projects/SPEC-001.json), keyed by linked_spec. Set by the navigator skill orchestrator after challenger passes. Agents resolve it against workspace_root from the recon manifest."
    },
    "spec_hash": {
      "type": "string",
      "description": "Content hash (e.g. sha256:<hex>) of the spec@1 file at spec_file_path as it existed when this plan was created. Set by planner. recon recomputes the current file's hash and compares it to this value to detect whether the spec changed after planning — a mismatch means the plan may not cover criteria added or changed since it was made."
    },
    "linked_requirement": {
      "type": "string",
      "description": "ID of the requirement@1 the source spec@1 implements. Propagated from spec@1.linked_requirement by planner so the full requirement-to-code chain is traceable without re-reading the spec."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
# Interface Implementer Coverage

## Outcome

When a plan changes a shared trait, interface, protocol, or expected method set, enumerate affected implementations before judging the plan complete. The result is a verified covered, uncovered, and uncertain inventory—not raw search matches.

## Apply when

Use this check when a task changes a shared contract, one implementation of that contract, or behavior expected across sibling adapters, providers, handlers, or backends.

## Candidate discovery

| Language | Candidate evidence |
| :--- | :--- |
| Rust | `impl Trait for Type`, trait bounds, constructors returning `dyn Trait` or `impl Trait` |
| TypeScript / JavaScript | `implements`, annotated factories or objects, registry entries, same-shaped adapters in sibling directories |
| Python | subclasses of an ABC, `Protocol` annotations, registered plugins, factories, or sibling objects with the required methods |
| Go | compile-time interface assertions, constructor returns, assignments to the interface, registrations, and concrete types with the required method set |

Search syntax first, then derive semantic candidates from the responsibility and architecture. Structural typing and implicit interfaces make text search incomplete by design.

## Evidence

1. Read the live contract and identify the behavior being changed.
2. Enumerate syntactic and semantic candidate implementations workspace-wide.
3. Read each candidate to confirm it intentionally participates in the contract.
4. Map confirmed implementations to plan tasks or an explicit reason they are unaffected.

Record:

- `covered`: a task or shared implementation addresses the changed behavior.
- `uncovered`: the implementation is affected but absent from the plan.
- `unaffected`: evidence shows the contract change cannot reach it.
- `uncertain`: dynamic registration, external packages, generated code, or missing access prevents a complete decision.

An empty search result is not completeness evidence until architecture-derived candidate sites have also been considered. Treat inaccessible or open-world implementations as a coverage gap, not a pass.
{
  "id": "SPEC-RELEASE-BASELINE-READINESS-006",
  "purpose": "Restore a green, current dependency-policy baseline for the exact Callisto release candidate without suppressing fixable security or registry findings.",
  "scope": "The workspace dependency declarations and Cargo.lock entries that select rustls and chacha20 through callisto-moon's Moon, Warpgate, Extism, and HTTP development/test dependency graph; current cargo-deny audit evidence; and focused Moon/WASM regression verification.",
  "non_goals": [
    "Broad dependency modernization unrelated to the confirmed audit failures.",
    "Adding RUSTSEC-2026-0285, rustls, chacha20, or a yanked-version exception to deny.toml.",
    "Changing Callisto's release product model, provider convergence model, setup resolution, or workspace membership semantics.",
    "Claiming that a lockfile-only update is safe without exercising the affected Moon, Extism, HTTP, and WASM test boundaries available in this repository."
  ],
  "api_surface": [],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "The committed dependency graph selects rustls 0.23.45 or newer throughout the workspace and a current cargo-deny audit no longer reports RUSTSEC-2026-0285; the fix uses a compatible dependency or lock update and does not add an advisory ignore.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "The committed dependency graph no longer selects yanked chacha20 0.10.1 through rand, retry-policies, reqwest-retry, Warpgate, Moon test utilities, or any sibling path; the fix does not add a yanked-version allowance.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "The update is the smallest compatible dependency transaction that fixes both confirmed failures. Every changed direct dependency constraint is justified by resolver evidence; unrelated packages are not upgraded merely because newer versions exist, and Cargo.lock remains reproducible from the checked-in manifests.",
      "is_error_case": false
    },
    {
      "id": "AC-004",
      "criterion": "The affected callisto-moon unit/integration tests, the real Moon/Extism sandbox tests, and `just wasm-check` pass after the update, proving the resolved runtime and HTTP/TLS stack still supports Callisto's current WASM plugin boundary.",
      "is_error_case": false
    },
    {
      "id": "AC-005",
      "criterion": "`just audit` passes against the advisory database current at verification time, and the remaining `just ci` stages pass. The audit timestamp and any environmental limitation are recorded; a stale or inaccessible advisory database is not reported as a green audit.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-RELEASE-BASELINE-READINESS-006.json",
  "reasoning": "The existing project-native audit is already the correct enforcement boundary. This specification narrows remediation to the two confirmed current-baseline failures so release-architecture work is not conflated with dependency modernization and cannot bypass a red candidate gate."
}
{
  "id": "SPEC-RELEASE-CONVERGENCE-002",
  "purpose": "Make release execution converge an immutable intent against exact observable provider state so interruption, lost runner state, and already-present objects cannot cause duplicate mutation, permanent Attempting records, or successful incomplete releases.",
  "scope": "The graph-private provider observation boundary, provider-specific exactness rules, execute and reconcile semantics, release-state and receipt responsibilities, remote tag and GitHub Release correctness, registry artifact verification, error reporting, and boundary tests against real subprocess behavior.",
  "non_goals": [
    "Distributed transactions or rollback of immutable registry publications.",
    "Treating the execution journal, a cache, a receipt, a workflow run, or absence of a recorded error as release authority.",
    "Automatically replacing or deleting an externally observed conflicting object.",
    "Compatibility with the current incomplete-success behavior or local-only reconcile output.",
    "Defining the product target roster or workflow approval policy, which are specified separately."
  ],
  "api_surface": [
    {
      "name": "OperationObservation",
      "signature": "enum OperationObservation { Absent, Incomplete(VerifiedPartialEvidence), Exact(VerifiedExternalEvidence), Conflict(ExternalConflict), Unverifiable(ObservationFailure) }",
      "description": "A closed graph-layer classification returned by observing one graph-private prepared operation against its provider; it preserves absence, a verified exact subset with identified missing work, exact equality, conflict, and inability to verify as different states.",
      "error_conditions": [
        "Provider authentication, authorization, rate limit, malformed output, unsupported client behavior, timeout, or transport failure produces Unverifiable, never Absent.",
        "An object with the intended name/version but different target, bytes, metadata, or an unexpected artifact produces Conflict, never Exact or Incomplete."
      ]
    },
    {
      "name": "ReleaseObservationEvidence",
      "signature": "versioned enum ReleaseObservationEvidence { RegistryArtifact { identity, digest, byte_length }, RemoteTag { name, target, annotation_digest }, ForgeRelease { release, lifecycle, asset_roster_digest }, ForgeAsset { release, name, digest, byte_length } }",
      "description": "The provider-neutral model-layer evidence schema used by observation reports and receipts; graph-private observations convert to it only after exact verification.",
      "error_conditions": [
        "Evidence identity does not exactly match its ReleaseOperationId.",
        "Provider stderr, credentials, endpoints, headers, arbitrary strings, or mutable configuration are supplied as durable evidence."
      ]
    },
    {
      "name": "observe_prepared",
      "signature": "observe_prepared(capability: &ValidatedReleaseIntent, operation: &ReleaseOperationId) -> OperationObservation",
      "description": "The single graph-private read boundary used before mutation, after mutation, by execute, and by reconcile for every operation role.",
      "error_conditions": [
        "The operation is not part of the validated intent or lacks an exact prepared provider identity.",
        "The provider cannot prove the operation's role-specific equality contract."
      ]
    },
    {
      "name": "converge_release",
      "signature": "converge_release(capability, validated_artifact_manifest, state_store, receipt_store, permit) -> ReleaseReceipt",
      "description": "Observes the canonical DAG in order, mutates only Absent operations or the closed missing-work set of Incomplete operations with satisfied observed prerequisites, re-observes postconditions, persists diagnostic state atomically, and returns only after a complete receipt is persisted.",
      "error_conditions": [
        "Any operation is Conflict or Unverifiable.",
        "An Absent or Incomplete operation remains non-Exact after its bounded effect attempt.",
        "Any prerequisite is not Exact in the current convergence pass.",
        "State or receipt persistence fails."
      ]
    },
    {
      "name": "reconcile_release",
      "signature": "reconcile_release(capability, validated_artifact_manifest, optional_state) -> ReleaseObservationReport",
      "description": "Performs the same complete external observation pass as execution without ApplyPermit or mutation and reports every exact, absent, incomplete, conflicting, or unverifiable operation.",
      "error_conditions": [
        "Intent, source, artifact, or prepared-input validation fails before provider observation.",
        "The report cannot cover every operation exactly once."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "Every operation role has one production observer that returns exactly Absent, Incomplete with a verified exact subset and closed missing-work set, Exact with safe typed evidence, Conflict with a closed reason, or Unverifiable with an actionable transient diagnostic. Execute, reconcile, pre-effect checks, post-effect checks, and interruption recovery call that same observer rather than reconstructing provider semantics in sibling paths. ExternalConflict is a closed graph diagnostic taxonomy; serializable success evidence uses the model-owned role-specific schema.",
      "is_error_case": false
    },
    {
      "id": "AC-002",
      "criterion": "Execution observes every operation in canonical DAG order regardless of whether the optional journal says Pending, Attempting, Published, AlreadySatisfied, Failed, or Blocked. Exact is recorded as satisfied without mutation; Absent or Incomplete mutates only the verified missing work at most once in that invocation and must be Exact on post-effect observation; Conflict or Unverifiable exits nonzero without mutating that operation or any dependent operation.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "A missing, unreadable, stale, or entirely lost execution-state file cannot widen authority or prevent recovery. A fresh runner given the same immutable intent and artifact manifest observes exact existing objects, skips their mutation, creates only absent objects, and converges to the same result; state remains an atomically persisted diagnostic journal bound to the intent.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Graph returns a complete typed observation report and receipt only after every intended operation is observed Exact in the same final pass and a matching receipt is atomically persisted. callisto-cli maps any Pending, Attempting, Failed, Blocked, Absent, Incomplete, Conflict, Unverifiable, missing operation, missing receipt, or receipt-write failure to nonzero exit and renders the incomplete operation and recovery action in text and complete JSON.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "callisto-model owns a strict versioned ReleaseObservationEvidence and ReleaseReceipt schema recording the intent digest, exact operation roster, role-specific safe identity/digest evidence, and whether each object was newly produced or already present. A graph-owned explicit-path ReleaseReceiptStore is the sole production writer and uses callisto_model::atomic::atomic_write. The receipt is output evidence only: execute and reconcile re-observe providers on every invocation and never accept receipt bytes as proof that an external object still exists or still matches.",
      "is_error_case": false
    },
    {
      "id": "AC-006",
      "criterion": "Registry observation compares each independently uploadable provider artifact with its matching expected RegistryPackage entry in the validated intent-bound artifact manifest: crates.io-compatible publication verifies the .crate checksum, npm verifies the packed tarball integrity or bytes, and PyPI verifies each expected distribution file name and SHA-256. Exact files are prominently reported and never republished; a verified exact subset with missing files is Incomplete and uploads only those missing files; a different digest, unexpected conflicting distribution, or provider response that cannot prove equality is fatal. Publication consumes the validated bytes, and any client that regenerates packaging proves the outgoing payload digest before submission.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "Graph's one observer delegates remote tag resolution, annotated-content comparison, push, and post-push observation to canonical callisto-vcs GitDataSource/GitAccess operations rather than a sibling raw-git protocol. The configured remote must prove the exact tag name resolves to the intended source commit and annotation digest; a matching local-only tag is neither Exact nor post-push confirmation, and a conflicting remote tag is fatal before any forge or asset operation becomes eligible.",
      "is_error_case": true
    },
    {
      "id": "AC-008",
      "criterion": "GitHub Release observation uses supported GitHub CLI or API arguments, classifies the real nonzero-exit HTTP 404 contract as Absent, preserves 401, 403, 429, 5xx, malformed, and transport results as Unverifiable, and proves release identity through the separately verified remote tag rather than target_commitish. ForgePrepare is Exact for the matching draft or its matching published successor and does not require future assets; ForgePublish classifies a matching draft or verified exact subset of assets as Incomplete and is Exact only when the release is published with the complete verified asset roster.",
      "is_error_case": true
    },
    {
      "id": "AC-009",
      "criterion": "GitHub asset observation addresses the exact ProductReleaseId and slot file name, downloads or queries immutable digest-capable data, and proves byte length and SHA-256 against the artifact manifest. An existing same-name asset with a different or unverifiable digest is fatal and is never overwritten; after an upload, the asset is re-observed as Exact before completion.",
      "is_error_case": true
    },
    {
      "id": "AC-010",
      "criterion": "Graph reconciliation is structurally read-only and returns a complete typed report for every operation, not merely a list of locally eligible Pending entries. It requires no ApplyPermit and invokes no registry publish, Git push, GitHub creation, or upload route. callisto-cli preserves the full report in JSON and exits nonzero when the intended release is not completely Exact.",
      "is_error_case": true
    },
    {
      "id": "AC-011",
      "criterion": "Boundary tests exercise realistic subprocess contracts: real Git with a bare remote for absent, exact, and conflicting tags; argv parsing compatible with the installed gh CLI; gh HTTP 404 with its real nonzero exit; 401, 403, 429, and 5xx failures; and local HTTP registry fixtures for absent, exact, conflicting, and unverifiable artifact metadata. An argv-insensitive fake or exit-zero 404 alone cannot satisfy this criterion.",
      "is_error_case": true
    },
    {
      "id": "AC-012",
      "criterion": "Interruption tests stop at each boundary between attempt persistence, each independently uploadable provider artifact, provider success, post-effect observation, terminal-state persistence, and receipt persistence, then resume with both the same journal and no journal on a fresh runner. Every case either uploads only verified missing work and converges without repeating an Exact effect or exits nonzero for Conflict/Unverifiable; no case can return successful incomplete state.",
      "is_error_case": true
    },
    {
      "id": "AC-013",
      "criterion": "The graph-private prepared operation remains the only effect and observation input. Raw artifact manifests are accepted only by a graph validation constructor that returns a non-serializable ValidatedArtifactManifest bound to the same ValidatedReleaseIntent; converge_release accepts only that capability. Provider adapters cannot accept free-form package, version, endpoint, tag, repository, asset name, or digest values from CLI flags, workflow environment, mutable configuration, or execution state after validation.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-RELEASE-CONVERGENCE-002.json",
  "revision_note": "Corrects the local-only, no-automatic-retry recovery semantics in the draft .claude release execution specifications. External state is authoritative for convergence; the journal is not.",
  "reasoning": "The smallest enforceable seam is between graph-private PreparedOperation data and execution state transition. Exact already-present behavior is defined against intent-bound build artifact digests, because package/version existence alone cannot distinguish a correct prior publish from a versioning mistake."
}
{
  "id": "SPEC-RELEASE-ORCHESTRATION-003",
  "purpose": "Define a fast, single-approval GitHub workflow that builds and executes the immutable Callisto product release, supports exact historical recovery on fresh runners, and proves the complete path in an isolated rehearsal before production.",
  "scope": "Release pull request authorization, GitHub Actions jobs and permissions, plan and artifact handoffs, four-target build fan-out, manual historical recovery, removal of the Environment approval, staging-rehearsal topology and failpoints, and retirement of superseded pre-v1 release routes.",
  "non_goals": [
    "A second human approval after the release pull request is merged.",
    "Using GitHub Actions cache, runner-local paths, mutable branches, or workflow output booleans as release authority.",
    "Publishing a rehearsal artifact to crates.io, npmjs.com, production PyPI, or the production Callisto GitHub Release namespace.",
    "Apple Developer ID signing or notarization.",
    "Preserving compatibility for pre-v1 release commands, workflow layouts, state files, or per-package GitHub release behavior."
  ],
  "api_surface": [
    {
      "name": "release workflow dispatch inputs",
      "signature": "workflow_dispatch { release_commit?: full CommitSha, source_run_id?: GitHubRunId, intent_digest?: IntentDigest, artifact_manifest_digest?: ArtifactDigest }",
      "description": "An explicit recovery route that either runs the newly merged release commit or retrieves the exact intent and build handoff from a prior run, then independently validates every binding before credentials are exposed.",
      "error_conditions": [
        "A recovery input is partial, malformed, expired, belongs to another repository, or does not bind the exact release commit and intent digest.",
        "The selected commit is not a verified merge of the managed release pull request."
      ]
    },
    {
      "name": "release rehearsal workflow",
      "signature": "rehearse-release(release_commit, failpoint?)",
      "description": "A reusable workflow invocation against an isolated GitHub repository and non-production registry endpoints that runs the same planning, build, attestation, execution, observation, and receipt boundaries as production.",
      "error_conditions": [
        "Any production registry endpoint, production tag namespace, or production release repository is selected.",
        "A configured interruption fails to resume on a new job/run and converge."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "The reviewed managed release pull request merge is the sole human approval event. The production workflow contains no environment-policy job, required-reviewer API check, protected Environment reviewer gate, or second manual approval; merge automatically proceeds through plan, build, attest, execute, and final verify when checks pass.",
      "is_error_case": false
    },
    {
      "id": "AC-002",
      "criterion": "The automatic path proves that the triggering commit is exactly one verified merge of the canonical managed release branch, then invokes the provider-neutral callisto release planner to derive and validate the immutable intent from that merge and its reviewed decision. Workflow verifies eligibility and transports files but never constructs operations, tags, package rosters, targets, or artifact names; direct pushes, unrelated pull requests, ambiguous merges, mutable branch tips, and mismatched intent/source fail.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "Planning has read-only repository permission and no release credentials. Build jobs have only source-read plus attestation/OIDC permissions. A separate read-only validation job validates the intent, source commit, complete artifact manifest, bytes, checksums, and attestations before execute starts. The execute job has job-scoped contents-write permission, repeats validation, and exposes registry secrets only to the final CLI invocation. Removing the Environment gate does not widen any earlier job's permissions.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "The build stage obtains a total matrix from the CLI's validated immutable intent and maps every declared slot exactly once; an unknown, missing, extra, or workflow-defaulted slot fails before build. It produces the aarch64-apple-darwin, x86_64-unknown-linux-musl, aarch64-unknown-linux-musl, and wasm32-wasip1 payloads plus all registry-package artifacts. A fan-in job validates the complete slot roster, creates deterministic archives and SHA256SUMS, records the artifact manifest, and ensures each required file has a GitHub attestation before execution can start.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "Intent, artifact-manifest, metadata, and receipt handoffs use strict model schemas, while payload/checksum bytes are validated by those schemas; all are downloaded outside the trusted source checkout and retained for a documented recovery window of at least seven days. Retention grants no authority: CLI revalidates every byte and identifier against the immutable intent, source commit, and original artifact-manifest digest. After expiry, a rebuild is usable only if it reproduces every original digest; otherwise recovery fails with an unrecoverable-handoff diagnostic rather than minting replacement expected bytes.",
      "is_error_case": false
    },
    {
      "id": "AC-006",
      "criterion": "A workflow_dispatch recovery can name an exact historical full release commit and either reproduce the original artifact-manifest digests or consume a named prior run whose intent and artifact-manifest digests are supplied. It verifies the original managed-PR merge, plan digest, source commit, artifact bindings, and original artifact identity, then uses external-state convergence; it never substitutes current main, latest, a different run's artifacts, newly chosen expected bytes, or runner-local state.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "The execute job invokes the core CLI once with the exact intent, artifact manifest, artifact directory, state path, and receipt path. Workflow shell does not publish registries, derive tag names, create releases, upload product assets, classify already-present responses, or decide completion independently of the CLI.",
      "is_error_case": false
    },
    {
      "id": "AC-008",
      "criterion": "The release workflow fails unless the CLI emits and the workflow validates a complete receipt for the same intent digest. The receipt and complete observation report are uploaded even on failure when safely available; a green execute or workflow conclusion without a valid complete receipt is impossible.",
      "is_error_case": true
    },
    {
      "id": "AC-009",
      "criterion": "The isolated rehearsal uses a dedicated non-production GitHub repository or equivalent isolated forge namespace plus non-production Cargo, npm, and PyPI registry endpoints and credentials. Repository and endpoint selection is resolved by graph before intent derivation and captured in typed intent/prepared bindings; workflow allowlists credentials and environment but cannot override those identities afterward. Allowlists fail closed before production registries, the production repository, or a production callisto@X.Y.Z tag can be addressed.",
      "is_error_case": true
    },
    {
      "id": "AC-010",
      "criterion": "One rehearsal covers managed release-PR merge, immutable plan, every real Callisto registry artifact build, all four product builds and native/WASM smoke tests, checksums, GitHub attestations, product tag, prepared release, asset uploads, final release publication, final observation, and receipt without production credentials. Separate representative npm and PyPI fixtures run through the same production adapters, including per-file interruption, exact rerun, digest conflict, and unverifiable-metadata cases even though Callisto itself currently publishes only Cargo packages.",
      "is_error_case": false
    },
    {
      "id": "AC-011",
      "criterion": "Rehearsal failpoints can stop after each provider mutation and before each following journal or receipt write. Each failpoint is resumed in a fresh job or run without its predecessor's RUNNER_TEMP state, and the second run must converge without duplicate mutation or false success. Conflict, unverifiable, expired-handoff, and wrong-source negative cases must also fail with actionable diagnostics.",
      "is_error_case": true
    },
    {
      "id": "AC-012",
      "criterion": "A proposed release-boundary implementation may be developed only in the isolated branch/rehearsal path and cannot be activated against production or used for the first production release until that exact candidate revision passes the full rehearsal suite. Later changes to release intent schemas, provider adapters, operation DAG, build matrix, attestation policy, or workflow handoff contract rerun the rehearsal gate before production activation.",
      "is_error_case": true
    },
    {
      "id": "AC-013",
      "criterion": "Superseded pre-v1 effect routes `plan-publish`, `publish`, `tag --plan`, and `filter-plan` are removed as independent release paths, along with their contradictory documentation. The `version`, changeset, status, matrix, and other non-effect capabilities required to prepare the release pull request remain. Any retained preview delegates to the canonical release planner and cannot publish, tag, upload, or create a release. There is one release plan/inspect/reconcile/execute family, one release-PR action, and one product-release workflow, with no Environment-gated, journal-authoritative, per-package GitHub release, or shell-owned effect path.",
      "is_error_case": false
    },
    {
      "id": "AC-014",
      "criterion": "All third-party Actions remain pinned to immutable commit SHAs; concurrency consumes a CLI-validated canonical ProductReleaseId and repository identity rather than reconstructing a tag in YAML; logs and uploaded diagnostics contain no credentials; and every shell interpolation crossing from workflow inputs is passed through a named environment variable and validated before use.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-RELEASE-ORCHESTRATION-003.json",
  "revision_note": "Supersedes the required-reviewer Environment and compatibility-window criteria in .claude/specs/SPEC-RELEASE-INTERFACES-013.json and related draft release specifications, based on the user's explicit pre-v1 product decisions.",
  "reasoning": "The rehearsal is not another approval gate. It is automated evidence that the same production boundaries work across real job isolation, provider protocols, attestations, and interruption. Thirty-day handoff retention supports recovery while the core still treats only the validated intent, artifact bytes, and observed provider state as authority."
}
{
  "id": "SPEC-RELEASE-PRODUCT-MODEL-001",
  "purpose": "Define one canonical coordinated product release and one intent-bound artifact inventory so Callisto can publish its registry packages and four supported distribution targets under exactly one callisto@X.Y.Z tag and GitHub Release.",
  "scope": "The durable release decision, operation identity, artifact-slot model, Callisto workspace release-unit selection, target roster, archive/checksum contract, and the graph-layer derivation that converts the coordinated train into registry, product-tag, forge-release, and asset-upload operations.",
  "non_goals": [
    "Independent package versioning or per-package GitHub tags and releases before version 1.0.",
    "Windows, Intel macOS, Linux glibc, or WASI targets other than wasm32-wasip1.",
    "Apple Developer ID signing, notarization, or use of a maintainer's personal signing identity.",
    "Provider observation, interruption recovery, or workflow job layout, which are specified separately.",
    "Backward compatibility for the current unreleased package-owned Tag, ForgeRelease, ArtifactSlotId, or release-intent JSON shapes."
  ],
  "api_surface": [
    {
      "name": "ProductName",
      "signature": "ProductName(String)",
      "description": "A validated provider-neutral canonical product identifier with one serialization; the Callisto workspace value is `callisto`.",
      "error_conditions": [
        "The name is empty, non-canonical, or contains bytes unsafe for a product tag."
      ]
    },
    {
      "name": "ProductReleaseId",
      "signature": "ProductReleaseId { product: ProductName, version: Version }",
      "description": "The provider-neutral identity of one coordinated product release; for this workspace it renders its sole Git tag as callisto@X.Y.Z.",
      "error_conditions": [
        "The product name is not a canonical safe identifier.",
        "The coordinated package roster contains more than one target version or a non-SemVer version."
      ]
    },
    {
      "name": "ReleaseOperationId",
      "signature": "enum ReleaseOperationId { RegistryArtifactPublish { package, version, registry, slot }, ProductTag { release, tag }, ForgePrepare { release, repository }, ArtifactUpload { release, slot }, ForgePublish { release, repository } }",
      "description": "An operation identity whose independently uploadable registry artifact variants remain package-owned while tag, one prepared-to-published forge object, and distribution-asset variants are product-owned.",
      "error_conditions": [
        "A package operation references a package/version outside the approved registry roster.",
        "A product operation references a different product release, tag, repository, or source identity.",
        "A duplicate operation identity or invalid prerequisite is supplied."
      ]
    },
    {
      "name": "ReleaseArtifactSlot",
      "signature": "enum ReleaseArtifactSlot { RegistryPackage { package, version, registry, format, file_name }, ProductAsset { release, target, file_name, provenance_policy }, ChecksumManifest { release, file_name, provenance_policy }, ReleaseMetadata { release, file_name, provenance_policy } }",
      "description": "The closed intent-declared inventory of exact registry upload artifacts and user-distributed product assets that the build handoff must produce.",
      "error_conditions": [
        "A slot is outside the approved release roster or product target roster.",
        "A file name or target is unsafe, duplicated, unknown, or mismatched to its slot kind.",
        "The slot roster does not have a matching build-manifest entry and reachable consuming operation."
      ]
    },
    {
      "name": "ReleaseArtifactManifest",
      "signature": "ReleaseArtifactManifest { intent_digest, source_commit, entries: Vec<ReleaseArtifactEntry> }",
      "description": "A canonical artifact set binding every registry package and product asset to exact bytes, SHA-256, byte length, source commit, and required provenance policy before credentials are available.",
      "error_conditions": [
        "The manifest does not exactly cover the intent-declared slot roster.",
        "A digest, length, source commit, target, file name, or attestation binding differs.",
        "The checksum manifest does not list every product payload exactly once with its manifest digest."
      ]
    },
    {
      "name": "ReleaseDistributionMetadataV1",
      "signature": "ReleaseDistributionMetadataV1 { product_release, intent_digest, source_commit, payloads, verification_policy }",
      "description": "The strict canonically serialized public installer contract, constructed from the immutable intent plus the validated product-payload entries that intent declares, then included in the final complete ReleaseArtifactManifest through its ReleaseMetadata slot without introducing a second roster.",
      "error_conditions": [
        "The product, intent, source, payload identity or digest, repository, signer workflow path/commit, or attestation policy differs from the validated manifest and slot policy.",
        "The metadata has unknown fields, a non-canonical order/encoding, duplicate entries, or an unsupported schema version."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "For a Callisto coordinated release, graph derivation emits exactly one ProductReleaseId with product `callisto`, one SemVer target shared by every releasable train member, and the exact tag `callisto@X.Y.Z`; divergent package target versions fail before an intent is written.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "ReleaseOperationId no longer requires every operation to be owned by a package: every independently uploadable registry artifact is keyed by exact ReleasePackageId, version, RegistryBindingId, and RegistryPackage slot; exactly one ProductTag follows all required registry artifacts; one ForgePrepare follows that tag; every ArtifactUpload follows the prepared release; and one ForgePublish follows every required asset. ForgePrepare is satisfied by the exact draft or its valid published successor, while ForgePublish is satisfied only by the published object with the complete asset roster. These operations address one ProductReleaseId and one GitHub Release object, and no per-package tag or forge-release operation can be derived for a coordinated train.",
      "is_error_case": false
    },
    {
      "id": "AC-003",
      "criterion": "callisto-graph's real workspace-to-ReleaseDecision derivation classifies callisto-fixtures as dev-only and excludes it before the durable decision is constructed. It may receive the coordinated source version update, but it requires no changeset, creates no registry, tag, forge, artifact, or checksum operation, and can never block release completion. CLI and workflow consume that decision without post-filtering it, and a test derives the real Callisto workspace decision to prove the exclusion.",
      "is_error_case": false
    },
    {
      "id": "AC-004",
      "criterion": "The product asset roster is a closed set of four payloads: a runnable `callisto` archive for aarch64-apple-darwin, a runnable statically linked `callisto` archive for x86_64-unknown-linux-musl, a runnable statically linked `callisto` archive for aarch64-unknown-linux-musl, and the callisto-moon plugin built for wasm32-wasip1. Any missing, duplicate, unexpected, differently targeted, or unsafe slot makes intent or manifest validation fail.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "The .github build and rehearsal jobs ad-hoc sign and locally verify the macOS ARM64 payload, make no Developer ID or notarization claim, verify both Linux payloads have the intended machine architecture and static linkage and pass a native `callisto --version` smoke test, and verify the release-profile wasm32-wasip1 payload with the repository's real Moon/Extism sandbox. The model records the closed target and provenance contract, and graph verifies the resulting intent-bound manifest before dispatch.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "The artifact manifest covers every independently uploadable registry artifact and every product payload with exact SHA-256 and byte length, is bound to the immutable intent digest and source commit, and rejects a byte change, slot substitution, source substitution, duplicate, omission, or extra entry before any release credential is exposed. Registry publication consumes those validated bytes; an adapter that regenerates packaging must prove the exact outgoing payload digest before submission rather than relying on a post-publication mismatch.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "The GitHub Release asset roster contains the four payloads, one deterministic `SHA256SUMS` file, and one canonically serialized `ReleaseDistributionMetadataV1` at `callisto-release-metadata.json`. callisto-model constructs metadata from the immutable intent and its validated product-payload entries, then the final complete ReleaseArtifactManifest includes the metadata and checksum slots. Metadata binds ProductReleaseId, intent digest, source commit, payload identities and digests, repository, immutable build workflow path and commit, and attestation policy without a second roster; it deliberately omits the checksum file's digest. SHA256SUMS lists each payload and the final metadata file exactly once, avoiding a circular digest. Every intent-declared slot carries typed policy in the intent digest, and all six uploaded files have matching GitHub artifact attestations; CI cannot substitute policy from mutable configuration.",
      "is_error_case": true
    },
    {
      "id": "AC-008",
      "criterion": "Every intent-declared artifact slot has exactly one production constructor, one build-manifest entry, and one reachable consumer operation; exhaustive matches plus an architecture test fail when a slot or operation variant is modeled but not derived, prepared, dispatched, observed, or covered by a boundary test.",
      "is_error_case": true
    },
    {
      "id": "AC-009",
      "criterion": "The release pull request and user-facing notes present one product version and one GitHub Release while still listing the registry packages and their publication targets. The GitHub Release remains draft until every required payload, checksum, and attestation is observed exact, then becomes published once; generated documentation and CLI help contain no supported path that creates per-crate Callisto GitHub releases or treats callisto-fixtures as a release unit.",
      "is_error_case": false
    },
    {
      "id": "AC-010",
      "criterion": "The revised durable types preserve the existing crate dependency direction: provider-neutral product, operation, and artifact identities live in callisto-model; release-unit resolution and intent derivation live in callisto-graph; callisto-cli and .github orchestration consume the intent and cannot independently invent the product tag, target roster, or artifact names.",
      "is_error_case": false
    },
    {
      "id": "AC-011",
      "criterion": "callisto-model replaces the current unreleased V1 package-owned operation, artifact-slot, intent, manifest, and digest shapes with one strict versioned successor containing ProductName, ProductReleaseId, package/product operation identities, the full artifact-slot enum, and ReleaseDistributionMetadataV1. ReleaseIntent, ReleaseArtifactManifest, and distribution metadata use one canonical roster and digest chain; all production callers migrate in the same change, and no parallel unbound inventory or compatibility decoder remains.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-RELEASE-PRODUCT-MODEL-001.json",
  "revision_note": "Supersedes the package-owned tag/forge and unreachable binary-slot assumptions in the draft .claude release specifications. The repository is pre-v1 and has no compatibility requirement for those unreleased shapes.",
  "reasoning": "The live ReleaseOperationId and ArtifactSlotId force package ownership, so adding a workflow matrix alone would preserve the wrong identity and leave uploads unreachable. Registry package bytes are included in the artifact handoff because exact already-present verification cannot be defined from package/version alone."
}
{
  "id": "SPEC-SETUP-IMMUTABLE-VERSION-005",
  "purpose": "Ensure setup-callisto installs exactly the requested immutable Callisto release and never substitutes a local checkout, mutable branch, or unpinned Git source after resolution failure.",
  "scope": "Composite-action source/version semantics, platform asset selection, product-tag to crate-version mapping, checksum and attestation verification, immutable fallbacks, failure diagnostics, and action contract tests.",
  "non_goals": [
    "Supporting Windows or Intel macOS before version 1.0.",
    "Using a mutable branch as an installation fallback.",
    "Building a local checkout unless source=local is explicitly selected.",
    "Apple Developer ID or notarization verification.",
    "Changing setup-callisto-wasm beyond sharing canonical product-version and verification helpers where applicable."
  ],
  "api_surface": [
    {
      "name": "setup-callisto inputs",
      "signature": "source: auto|release|registry|local; version: latest|X.Y.Z|callisto@X.Y.Z",
      "description": "An explicit resolver in which non-local modes produce one immutable semantic version before any download or install, and local mode alone builds the checked-out source.",
      "error_conditions": [
        "source=local is combined with an exact release version.",
        "latest cannot be resolved to one immutable version.",
        "An exact asset or registry package is unavailable or fails verification.",
        "The current operating system or architecture is unsupported."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "An explicit X.Y.Z or callisto@X.Y.Z request resolves to that one semantic version. In source=auto only a confirmed not-found release asset may fall back to the registry package with that identical version; authorization, rate-limit, 5xx, timeout, transport, malformed response, checksum, attestation, extraction, or version failures are terminal. source=release and source=registry never switch sources. If the selected immutable source cannot supply and verify the exact version, setup exits nonzero and never invokes unpinned cargo install --git.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "latest is resolved once to an immutable product version before installation and that resolved version is printed. Fallback between release assets and the registry retains that exact resolved version; it never asks each source independently for its latest version and never falls back to a branch.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "source=local is the only mode that builds the current checkout, requires a Callisto workspace, rejects an exact release-version input, and reports the checkout commit and built CLI version. Merely running inside the Callisto monorepo cannot override source=auto, release, or registry.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Release-asset installation supports exactly aarch64-apple-darwin, x86_64-unknown-linux-musl, and aarch64-unknown-linux-musl. Unsupported operating systems and architectures fail with an actionable diagnostic rather than selecting a Linux or amd64 default.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "Before extraction or PATH modification, the commit-pinned setup helper independently anchors the allowed `orin-dx/callisto` repository and release-build workflow path, then consumes SPEC-RELEASE-PRODUCT-MODEL-001's versioned public `callisto-release-metadata.json` contract and requires its repository/workflow claims to match that allowlist. It verifies metadata and the selected payload against the exact product tag, source commit, SHA256SUMS, immutable workflow commit, and GitHub artifact attestations, then requires the installed binary to report the resolved version. Downloaded metadata can narrow or bind policy but can never authorize its own repository or workflow trust root.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "The resolver has table-driven action tests covering every source mode, both exact-version spellings, latest pinning, local-checkout precedence, each supported platform mapping, every unsupported-platform error, release-to-registry fallback with the same pinned version, and proof that no failure path executes an unpinned Git installation.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "One checked-in `.github` helper owns source resolution, ProductReleaseId-equivalent tag/version parsing, asset mapping, checksum verification, metadata verification, and attestation verification for setup-callisto and setup-callisto-wasm. The helper consumes the release contract and cannot derive release rosters or names from mutable checkout configuration; any artifact-type-specific divergence is explicit and tested.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-SETUP-IMMUTABLE-VERSION-005.json",
  "reasoning": "The existing action conflates checkout detection, source choice, and fallback. Making the source mode explicit removes the silent exact-version-to-main transition while retaining a fast local mode for repository workflows."
}
{
  "id": "SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004",
  "purpose": "Make workspace membership a fail-closed authority so malformed Cargo, npm, pnpm, or uv configuration cannot silently broaden package discovery or a release roster.",
  "scope": "Root membership readers, format-specific absence and invalidity rules, glob compilation, IgnoreWalkLocator propagation, diagnostics, and release-boundary regression tests for Cargo, npm/package.json, pnpm-workspace.yaml, and uv/Python workspaces.",
  "non_goals": [
    "Changing the valid membership or exclusion semantics of Cargo, npm, pnpm, Yarn-compatible package.json workspaces, or uv.",
    "Treating an absent workspace authority file or absent workspace field as malformed when another supported root marker legitimately owns discovery.",
    "Recovering from malformed configuration by scanning more directories.",
    "Changing manifest CST editing or package identity parsing outside discovery."
  ],
  "api_surface": [
    {
      "name": "MembershipAuthority",
      "signature": "pub(crate) enum MembershipAuthority<T> { Absent, Present(T) } returned as Result<MembershipAuthority<T>, LocateError>",
      "description": "A shared semantic result that keeps a genuinely absent authority distinct from a valid authority and represents unreadable, unparseable, invalid-shape, or invalid-glob authority as an error.",
      "error_conditions": [
        "An authority file exists but cannot be read or parsed.",
        "A present members, exclude, workspaces, or packages field has the wrong shape or a non-string item.",
        "A declared membership or exclusion glob is invalid."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "Cargo and uv use one shared typed TOML membership reader that returns Absent only when the manifest or relevant workspace table is genuinely absent, Present for a valid table including a deliberately empty members list, and a miette diagnostic error for read failure, TOML parse failure, malformed members/exclude fields, or invalid globs.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "npm package.json and pnpm-workspace.yaml use the same Absent/Present/error semantics with format-specific parsers. A valid omission of pnpm `packages` follows the explicitly supported pnpm version's documented default and remains authoritative; an unreadable file, invalid or empty YAML document, present wrongly typed packages field, non-string item, or invalid glob fails and never falls through to package.json or admit-all.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "All read_*_membership functions and glob compilation return Result<MembershipAuthority<_>, LocateError>. IgnoreWalkLocator resolves all selected root authorities before constructing or traversing the walk, returns an error when any authority is invalid, and cannot produce a partial project list. Workspace::load, every planning command, release decision derivation, and execution-time intent revalidation propagate that error before a decision, intent, manifest write, Git mutation, credential read, or provider invocation.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Absent authority retains the documented admit-all behavior only for the ecosystem whose authority is truly absent. Present empty membership denies non-root members, exclusions remain effective, hybrid roots retain their current valid behavior, and valid precedence between pnpm and package.json is unchanged.",
      "is_error_case": false
    },
    {
      "id": "AC-005",
      "criterion": "Diagnostics are graph-owned LocateError variants with unique stable codes and identify the ecosystem, safe workspace-relative authority path, invalid field or parser class, source, and remediation without exposing raw file contents. Filesystem parsing errors are not placed in callisto-model or callisto-manifests.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "Tests replace every current malformed-to-absent assertion with a failure assertion, cover each ecosystem's invalid syntax, wrong field shape, non-string item, and invalid glob, and include an end-to-end release-plan test proving malformed root authority cannot add an otherwise discoverable package to the release decision.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "All Cargo/uv membership call sites and all npm/pnpm membership call sites migrate in the same change; no second bool, Option, empty-glob, or best-effort parser remains able to encode invalid authority as absence or allow-all.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json",
  "reasoning": "Cargo and uv share an implementation boundary, while npm and pnpm require format-specific parsing and precedence. All four share the semantic result and fail-closed policy; cross-language setup resolution is deliberately not forced into this Rust abstraction."
}

