jobs:
  workflow-contracts:
    name: Workflow Contracts
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
      - name: Install workflow validation tools
        uses: taiki-e/install-action@e67fa11c4b9316fa714ddf0abed07a0c3143b95b # v2
        with:
          tool: ripgrep,zizmor@1.30.0
      - name: Lint workflow and action metadata
        # actionlint v1.7.12 predates GitHub's documented $/ self-repository
        # syntax. Keep all other actionlint diagnostics strict.
        uses: docker://rhysd/actionlint@sha256:9d36088643581e728c969f35141f88139fec77280b2be23c1f66f8e40e1025e7 # v1.7.12
        with:
          # Docker action arguments are passed directly, rather than through a
          # shell. Keep the exception as one argument so its regex is intact.
          args: -color -ignore=\$/.+
      - name: Audit workflow and action security
        run: zizmor --offline --strict-collection .
      - name: Verify pinned actions
        run: bash .github/tests/verify-action-pins.sh
      - name: Verify durable release workflow contract
        run: bash .github/tests/verify-release-workflow-contract.sh
      - name: Verify Release-PR action contract
        run: env PATH=/usr/bin:/bin bash .github/actions/callisto-action/tests/test_release_pr_contract.sh

  fmt:
    name: Code Formatting (Moon & Just)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
