rtk proxy python3 -c 'import json,jsonschema,pathlib,hashlib; base=pathlib.Path("/Users/gabe/.codex/plugins/cache/wisp-plugins/navigator/2.3.2/shared/schemas"); tasks={}; plans=[]; [(jsonschema.Draft202012Validator(json.loads((base/schema).read_text())).validate(json.loads(p.read_text())),print("SCHEMA",p)) for folder,schema in [("specs","spec@1.json"),("projects","plan@1.json")] for p in pathlib.Path("docs",folder).glob("*.json")];
for p in pathlib.Path("docs/projects").glob("*.json"):
 d=json.loads(p.read_text());s=json.loads(pathlib.Path(d["spec_file_path"]).read_text());plans.append(d);print("HASH",d["linked_spec"],d["spec_hash"]=="sha256:"+hashlib.sha256(pathlib.Path(d["spec_file_path"]).read_bytes()).hexdigest());print("UNCOVERED",[a["id"] for a in s["acceptance_criteria"] if not any(a["id"] in t.get("covers_criteria",[]) for t in d["tasks"])]);tasks.update({d["linked_spec"]+":"+t["id"]:(d,t) for t in d["tasks"]})
pending=set(tasks);done=set()
while pending:
 ready=sorted(k for k in pending if all((v if ":" in v else tasks[k][0]["linked_spec"]+":"+v) in done for v in tasks[k][1].get("depends_on",[])))
 if not ready:print("CYCLE/UNKNOWN",pending);break
 print("READY",ready);pending.difference_update(ready);done.update(ready)
'

