text((await tools.exec_command({cmd:"rtk proxy jq '{tasks:[.tasks[]|select(.id=="ORCH-004" or .id=="ORCH-001" or .id=="ORCH-002" or .id=="ORCH-007")|{id,depends_on,files,steps}]}' docs/projects/SPEC-RELEASE-ORCHESTRATION-003.json && rtk proxy jq '{tasks:[.tasks[]|select(.id=="PM-007" or .id=="PM-008")|{id,depends_on}]}' docs/projects/SPEC-RELEASE-PRODUCT-MODEL-001.json && rtk proxy jq '{tasks:[.tasks[]|{id,depends_on}]}' docs/projects/SPEC-SETUP-IMMUTABLE-VERSION-005.json","workdir":"/private/tmp/callisto-release-recovery","max_output_tokens":6500})).output);
text((await tools.exec_command({cmd:"rtk proxy python3 -c 'import json,pathlib;tasks={};
for p in pathlib.Path("docs/projects").glob("*.json"):
 d=json.loads(p.read_text());tasks.update({d["linked_spec"]+":"+t["id"]:(d,t) for t in d["tasks"]})
pending=set(tasks);done=set()
while pending:
 ready=sorted(k for k in pending if all((v if ":" in v else tasks[k][0]["linked_spec"]+":"+v) in done for v in tasks[k][1].get("depends_on",[])))
 if not ready: print("CYCLE/UNRESOLVED",pending);break
 pending.difference_update(ready);done.update(ready)
else:print("ALL TASKS RESOLVE; NO CYCLES")'","workdir":"/private/tmp/callisto-release-recovery","max_output_tokens":1500})).output);

